// Steam + Millennium (live): liest Steam-Daten ueber pc.steam() im 1-s-Takt.
// Nur Lesen: die Daten kommen vom Agenten, nicht aus Dateien.
var letzt = null;          // letzter gemeldeter Status (Aenderungserkennung)
var einmalig = {};         // einmalige Hinweise (kein Dauer-Spam)

function zahl(wert) {
  var n = Number(wert);
  return isFinite(n) ? n : 0;
}

// Fortschritt immer mit genau einer Nachkommastelle.
function prozentText(wert) {
  return zahl(wert).toFixed(1);
}

// Name eines Downloads, mit Ersatzname falls das Feld fehlt.
function nameVon(eintrag, nummer) {
  var name = eintrag && eintrag.name ? String(eintrag.name) : "";
  if (name === "") {
    name = "App " + String(eintrag && eintrag.app_id ? eintrag.app_id : nummer);
  }
  return name;
}

// "4.2 MB/s" - der Agent liefert Bytes pro Sekunde (speed_bps).
// Netzwerk-Tempo wird dezimal gerechnet (wie im Steam-Client), nicht binaer.
function tempoText(bps) {
  var wert = zahl(bps);
  if (wert <= 0) {
    return "";
  }
  if (wert >= 1000000000) {
    return (wert / 1000000000).toFixed(1) + " GB/s";
  }
  if (wert >= 1000000) {
    return (wert / 1000000).toFixed(1) + " MB/s";
  }
  if (wert >= 1000) {
    return Math.round(wert / 1000) + " KB/s";
  }
  return Math.round(wert) + " B/s";
}

// "noch 12 Min." - Restzeit aus eta_seconds.
function restText(sekunden) {
  var s = zahl(sekunden);
  if (s <= 0) {
    return "";
  }
  if (s < 60) {
    return s + " Sek.";
  }
  if (s < 3600) {
    return Math.round(s / 60) + " Min.";
  }
  return Math.round(s / 3600) + " Std.";
}

function downloadZeile(eintrag, nummer) {
  var name = nameVon(eintrag, nummer);
  var p = prozentText(eintrag.percent);
  var z = name + " " + p + "%";
  var t = tempoText(eintrag.speed_bps);
  if (t) {
    z += " · " + t + "/s";
  }
  var r = restText(eintrag.eta_seconds);
  if (r) {
    z += " · noch " + r;
  }
  return z;
}

function steamStatusText(s) {
  var teile = [];
  if (s.detected) {
    teile.push("Steam: " + s.steam_path);
  } else {
    teile.push("Steam nicht erkannt");
  }
  if (s.millennium) {
    teile.push("Millennium erkannt");
  }
  if (s.running) {
    teile.push("Steam lauft");
  }
  if (s.downloading && s.downloads && s.downloads.length > 0) {
    var kopf = s.downloads[0];
    teile.push(downloadZeile(kopf, 1));
    if (s.downloads.length > 1) {
      teile.push("+" + (s.downloads.length - 1) + " weitere");
    }
  } else if (s.detected) {
    teile.push("Keine Downloads");
  }
  return teile.join(" | ");
}

function aenderungErkannt(alt, neu) {
  if (!alt) return true;
  if (alt.detected !== neu.detected) return true;
  if (alt.millennium !== neu.millennium) return true;
  if (alt.running !== neu.running) return true;
  if (alt.downloading !== neu.downloading) return true;
  if (alt.progress_percent !== neu.progress_percent) return true;
  if (alt.speed_bps !== neu.speed_bps) return true;
  if (alt.eta_seconds !== neu.eta_seconds) return true;
  if (alt.app_name !== neu.app_name) return true;
  if ((alt.downloads || []).length !== (neu.downloads || []).length) return true;
  return false;
}

function activate() {
  if (!einmalig.aktiviert) {
    pc.log("Millennium-Live aktiv (pc.steam() alle 1s, nur bei Aenderung)");
    einmalig.aktiviert = true;
  }
}

function tick() {
  try {
    var s = pc.steam();
    if (!s || !s.detected) {
      if (letzt && !einmalig.steamWeg) {
        pc.log("Steam nicht erkannt");
        einmalig.steamWeg = true;
      }
      letzt = null;
      return;
    }
    einmalig.steamWeg = false;
    if (aenderungErkannt(letzt, s)) {
      pc.log("> " + steamStatusText(s));
      letzt = s;
    }
  } catch (e) {
    if (!einmalig.fehler) {
      pc.log("Fehler beim Lesen von Steam: " + String(e));
      einmalig.fehler = true;
    }
  }
}
